{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_758b3ba76bcac41aa321f2ee", "claim_ids": ["claim_3865bd024aac66aa407b389e", "claim_5a23397e16b412f9f0cc0ad4"], "query_ids": ["q_391"], "claims": [{"claim_id": "claim_3865bd024aac66aa407b389e", "quote": "In 2025, preliminary U.S. anti-dumping duties on Chinese graphite imports reached 93.5%, contributing to effective tariff levels near 160% for certain battery-related imports.", "url": "https://market.us/report/battery-separator-market", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "near 160%"}}, {"claim_id": "claim_5a23397e16b412f9f0cc0ad4", "quote": "In 2025, preliminary U.S. anti-dumping duties on Chinese graphite imports reached 93.5%, contributing to effective tariff levels near 160% for certain battery-related imports.", "url": "https://market.us/report/battery-separator-market", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "preliminary U.S. anti-dumping duties", "affected_product": "Chinese graphite imports", "duty_rate": "93.5%", "effective_date": "2025", "reported_policy_status": "preliminary"}}]}, {"pair_id": "conflict_01935bbfdc568e7ea297e6fc", "claim_ids": ["claim_5a23397e16b412f9f0cc0ad4", "claim_d98c55d483278a875e8b868a"], "query_ids": ["q_391"], "claims": [{"claim_id": "claim_5a23397e16b412f9f0cc0ad4", "quote": "In 2025, preliminary U.S. anti-dumping duties on Chinese graphite imports reached 93.5%, contributing to effective tariff levels near 160% for certain battery-related imports.", "url": "https://market.us/report/battery-separator-market", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "preliminary U.S. anti-dumping duties", "affected_product": "Chinese graphite imports", "duty_rate": "93.5%", "effective_date": "2025", "reported_policy_status": "preliminary"}}, {"claim_id": "claim_d98c55d483278a875e8b868a", "quote": "A 93.5 percent tariff on Chinese graphite – the primary anode material in virtually all lithium-ion batteries – took effect, representing one of the most significant raw material tariffs in US manufacturing history.", "url": "https://www.totexmfg.com/battery-pack-tariffs-oem-2026", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "93.5 percent tariff", "affected_product": "Chinese graphite", "duty_rate": "93.5 percent"}}]}, {"pair_id": "conflict_f716f014067c1c4667027b39", "claim_ids": ["claim_4e306a8dfbf98e43cfef6c05", "claim_4eadf13066c92908d0964740"], "query_ids": ["q_391"], "claims": [{"claim_id": "claim_4e306a8dfbf98e43cfef6c05", "quote": "The IEA noted that proposed Chinese export controls on battery materials and production technologies could tighten supply availability for lithium-ion battery systems and related components outside China.", "url": "https://market.us/report/battery-separator-market", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "proposed Chinese export controls", "affected_product": "battery materials and production technologies", "reported_policy_status": "proposed"}}, {"claim_id": "claim_4eadf13066c92908d0964740", "quote": "Pomega Enerji Depolama Teknolojileri is a lithium-ion battery importer.", "url": "https://acculonenergy.com/navigating-the-ebb-flow-of-todays-unpredictable-tariff-tides-the-impact-on-the-global-domestic-battery-industry", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Pomega Enerji Depolama Teknolojileri"}}]}, {"pair_id": "conflict_a205f55e8afef76096716590", "claim_ids": ["claim_40a20919561b3e88a8640e11", "claim_fd33223c59d8eb41952029ae"], "query_ids": ["q_391"], "claims": [{"claim_id": "claim_40a20919561b3e88a8640e11", "quote": "Section 232 investigations could add new tariff measures not yet in place", "url": "https://www.totexmfg.com/battery-pack-tariffs-oem-2026", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232 investigations", "reported_policy_status": "could add new tariff measures not yet in place"}}, {"claim_id": "claim_fd33223c59d8eb41952029ae", "quote": "The Supreme Court struck down tariffs imposed under the International Emergency Economic Powers Act (IEEPA) in February 2026, but the administration continued pursuing battery-related trade barriers through other legal authorities including Section 232 investigations, while maintaining existing measures including a 10 percent import surcharge under Section 122.", "url": "https://www.totexmfg.com/battery-pack-tariffs-oem-2026", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"legal_authority": "International Emergency Economic Powers Act (IEEPA)", "duty_rate": "10 percent import surcharge", "effective_date": "February 2026"}}]}, {"pair_id": "conflict_94294ea05aa5c8083d2f2f05", "claim_ids": ["claim_780b43a253ec599ce7412559", "claim_dd2a7d37c8f82f0ee8981b2a"], "query_ids": ["q_392"], "claims": [{"claim_id": "claim_780b43a253ec599ce7412559", "quote": "While copper prices have somewhat stabilized in the weeks since a 50% import tariff on the metal went into effect, the battery energy storage industry is bracing for higher prices and supply chain disruptions in the near future.", "url": "https://pv-magazine-usa.com/2025/09/08/polymer-batteries-could-help-protect-the-energy-storage-industry-from-copper-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "import tariff on the metal", "duty_rate": "50%", "effective_date": "weeks since"}}, {"claim_id": "claim_dd2a7d37c8f82f0ee8981b2a", "quote": "Though refined copper has been granted a temporary exemption, it might not be enough to shield the market, as semi-finished products are still vulnerable.", "url": "https://pv-magazine-usa.com/2025/09/08/polymer-batteries-could-help-protect-the-energy-storage-industry-from-copper-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}]}, {"pair_id": "conflict_0a58b0cf2fd6cbde6d935953", "claim_ids": ["claim_47d5ece55f090bcf0d342da3", "claim_6ceee7a841d96f1693ac2988"], "query_ids": ["q_394"], "claims": [{"claim_id": "claim_47d5ece55f090bcf0d342da3", "quote": "The incoming administration of President-elect Donald Trump has proposed further increasing the duty as high as 60%, CEA said.", "url": "https://www.utilitydive.com/news/us-battery-storage-lfp-nmc-market-possible-significant-tariff-impacts-clean-energy/737317", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "duty", "duty_rate": "60%"}}, {"claim_id": "claim_6ceee7a841d96f1693ac2988", "quote": "In September, the outgoing administration of President Joe Biden finalized a proposal to increase the Section 301 import duty on Chinese-made lithium-ion batteries from 7.5% to 25%, beginning on Jan. 1, 2026.", "url": "https://www.utilitydive.com/news/us-battery-storage-lfp-nmc-market-possible-significant-tariff-impacts-clean-energy/737317", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301", "duty_rate": "25%", "effective_date": "Jan. 1, 2026", "reported_policy_status": "proposal"}}]}, {"pair_id": "conflict_e197c59921584322a1b2ea9c", "claim_ids": ["claim_03751585484a722c8d2c3c14", "claim_6e3c1fc553d7502bd387a698"], "query_ids": ["q_396"], "claims": [{"claim_id": "claim_03751585484a722c8d2c3c14", "quote": "Since April 2025, a deal effective August 1, 2025, set tariffs at 15%. The 50% tariff rate on aluminum, steel, and copper products remains in place.", "url": "https://acculonenergy.com/navigating-the-ebb-flow-of-todays-unpredictable-tariff-tides-the-impact-on-the-global-domestic-battery-industry", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "15%", "effective_date": "August 1, 2025"}}, {"claim_id": "claim_6e3c1fc553d7502bd387a698", "quote": "BMS electronics sourced from China carry 25 to 30 percent tariffs that can meaningfully affect smart battery pack pricing.", "url": "https://www.totexmfg.com/battery-pack-tariffs-oem-2026", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Totex", "duty_rate": "25 to 30 percent"}}]}, {"pair_id": "conflict_eac6a6be1b75fa3aede16180", "claim_ids": ["claim_6e3c1fc553d7502bd387a698", "claim_7664bdc7dcfc6055adcdcb13"], "query_ids": ["q_396"], "claims": [{"claim_id": "claim_6e3c1fc553d7502bd387a698", "quote": "BMS electronics sourced from China carry 25 to 30 percent tariffs that can meaningfully affect smart battery pack pricing.", "url": "https://www.totexmfg.com/battery-pack-tariffs-oem-2026", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Totex", "duty_rate": "25 to 30 percent"}}, {"claim_id": "claim_7664bdc7dcfc6055adcdcb13", "quote": "Since April 2025, a trade deal effective August 1, 2025, set a 15% tariff rate on Japanese goods. Steel, aluminum, and copper products from Japan remain subject to a 50% tariff rate.", "url": "https://acculonenergy.com/navigating-the-ebb-flow-of-todays-unpredictable-tariff-tides-the-impact-on-the-global-domestic-battery-industry", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "15%", "effective_date": "August 1, 2025"}}]}, {"pair_id": "conflict_b2e7ff01a067464f43b506af", "claim_ids": ["claim_38686e1a114c6a3e6d472842", "claim_5c6447ad5bfca0c4a15aa73c"], "query_ids": ["q_399"], "claims": [{"claim_id": "claim_38686e1a114c6a3e6d472842", "quote": "The cost of steel has risen from around 35 cents per pound prior to February 2025 to approximately 50 cents per pound, a 43% increase. The steel trays, being one of the most expensive components of the battery, could see a cost increase of about 30%", "url": "https://www.stryten.com/the-impact-of-critical-mineral-bans-and-steel-tariffs-on-battery-manufacturing", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "43% increase"}}, {"claim_id": "claim_5c6447ad5bfca0c4a15aa73c", "quote": "The recent 25% tariff on imported steel has significant implications for battery manufacturing costs. The tariff has led to increased prices in anticipation of increased domestic demand and constrained supply.", "url": "https://www.stryten.com/the-impact-of-critical-mineral-bans-and-steel-tariffs-on-battery-manufacturing", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% tariff on imported steel"}}]}, {"pair_id": "conflict_75d35dc9991889bce4924ed8", "claim_ids": ["claim_65b74d6de0415ef4c482d213", "claim_7aa14e1ddafd7b66fee99210"], "query_ids": ["q_399"], "claims": [{"claim_id": "claim_65b74d6de0415ef4c482d213", "quote": "effective March 12, 2025, the current administration reinstated 25% tariffs on global steel imports and increased tariffs on global aluminum imports to 25%. These measures significantly affect the battery manufacturing industry", "url": "https://www.stryten.com/the-impact-of-critical-mineral-bans-and-steel-tariffs-on-battery-manufacturing", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% tariffs on global steel imports", "effective_date": "March 12, 2025"}}, {"claim_id": "claim_7aa14e1ddafd7b66fee99210", "quote": "the possibility of a far higher 25 percent duty after Trump’s reciprocal tariffs resume in July", "url": "https://www.eenews.net/articles/how-a-trade-war-could-move-american-evs-out-of-reach", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25 percent", "announcement_date": "July"}}]}]}

